#: MURaM magnetic corrections Δw (added to w), [M/H] = 0 MURaM stars; linear in
#: Teff, clamped outside 3196-6807 K, applied at all log g and [M/H]
#: (an extrapolation); MURaM ratios held constant below mu = 0.1.
_CORR_TEFF = np.array([3196.0, 3518.0, 3707.0, 4543.0, 5240.0, 5778.0, 6807.0])
_CORR = {
    "ssd": [[6.700000e-05, -1.700000e-05, -1.100000e-05, 1.000000e-04], [5.010000e-04, 2.970000e-04, -6.270000e-04, 1.890000e-04], [-3.100000e-04, 1.710000e-04, -8.280000e-04, -1.023000e-03], [2.400000e-05, -1.070000e-04, -1.850000e-04, -1.740000e-04], [-5.530000e-04, -5.640000e-04, 5.580000e-04, 1.090000e-04], [-2.111000e-03, 7.290000e-04, 1.090000e-03, -9.690000e-04], [-1.449000e-03, 3.250000e-03, 1.481000e-03, -4.618000e-03]],
    "B100G": [[-1.850000e-04, 3.700000e-04, -4.140000e-04, -5.260000e-04], [2.320000e-04, 7.000000e-04, -7.190000e-04, -4.100000e-04], [-1.373000e-03, 4.570000e-04, -2.000000e-06, -1.822000e-03], [-8.520000e-04, -1.700000e-03, 1.627000e-03, -3.950000e-04], [-2.927000e-03, -4.396000e-03, 4.050000e-03, -1.416000e-03], [-6.486000e-03, -2.438000e-03, 5.507000e-03, -5.029000e-03], [-9.808000e-03, -3.937000e-03, 1.411600e-02, -5.712000e-03]],
    "B200G": [[-3.470000e-04, 1.069000e-03, -1.359000e-03, -1.429000e-03], [-1.290000e-04, 1.320000e-03, -1.918000e-03, -1.650000e-03], [-2.920000e-03, 1.091000e-03, -4.680000e-04, -3.427000e-03], [-3.163000e-03, -3.137000e-03, 4.055000e-03, -3.083000e-03], [-8.331000e-03, -6.191000e-03, 7.849000e-03, -7.192000e-03], [-1.204700e-02, -6.222000e-03, 1.101800e-02, -8.188000e-03], [-1.920600e-02, -9.356000e-03, 2.602500e-02, -1.495300e-02]],
    "B300G": [[-4.690000e-04, 1.538000e-03, -2.284000e-03, -2.154000e-03], [-6.070000e-04, 2.208000e-03, -2.832000e-03, -2.297000e-03], [-3.816000e-03, 1.674000e-03, -1.256000e-03, -4.565000e-03], [-5.951000e-03, -4.750000e-03, 5.339000e-03, -5.706000e-03], [-1.405400e-02, -9.489000e-03, 1.169400e-02, -1.121100e-02], [-1.946900e-02, -5.079000e-03, 1.564900e-02, -2.056100e-02], [-3.369300e-02, -1.131300e-02, 4.452500e-02, -3.580500e-02]],
}


def _delta_w(t, state, dt):
    """Δw at Teff t (n,): piecewise linear, clamped at the ends (MLX ops)."""
    T, D = _CORR_TEFF, np.array(_CORR[state])
    slope = mx.array(np.diff(D, axis=0) / np.diff(T)[:, None], dtype=dt)
    seg = mx.clip(t[:, None] - mx.array(T[:-1], dtype=dt), 0.0, mx.array(np.diff(T), dtype=dt))
    return mx.array(D[0], dtype=dt) + seg @ slope


def _unpack(s, shape, dtype):
    return np.frombuffer(zlib.decompress(base64.b64decode(s)), dtype).astype(float).reshape(shape)


def _grid():
    """The tensor grid: the models (scaled), their rows, the axes, and the value
    of every grid node (a model, the mix of two models in _FILL, or NaN)."""
    X = _unpack(_GRID, (_N, 3), "<f8") / SCALE
    Y = _unpack(_DATA, (_N, NW + 2), "<f4")
    axes = [np.unique(np.round(X[:, k], 9)) for k in range(3)]
    shape = tuple(len(a) for a in axes)
    ijk = np.stack([np.searchsorted(a, np.round(X[:, k], 9)) for k, a in enumerate(axes)], -1)
    Yn = np.full((int(np.prod(shape)), Y.shape[1]), np.nan)
    Yn[np.ravel_multi_index(tuple(ijk.T), shape)] = Y
    for node, a, b, t in _FILL:
        Yn[node] = (1 - t) * Y[a] + t * Y[b]
    return X, Y, axes, shape, Yn


_X, _Y, _AXES, _SHAPE, _YN = _grid()
_VALID = np.isfinite(_YN[:, 0])
_YN0 = np.where(_VALID[:, None], _YN, 0.0)

_X0 = _X - _X.min(0)                    # the nearest-model search, in small numbers
_CONST = {}
_MU = np.linspace(0.0, 1.0, 2001)


def _basis():
    """Rows: S1..S4 on (1 - mu^4, (1 - mu^2)^2, P_e0, P_e1); with g = dI/dx,
    S3: I(0) = 0, g(1) = g'(1) = g''(1) = 0; S4: I(0) = 0, g(1) = g'(1) = g''(0) = 0."""
    (e0, e1), (a0, a1) = EPS, (1 / (e ** -2 - (1 + e) ** -2) for e in EPS)
    g = lambda x: [2 * x, 2 * (1 - x), 2 * a0 * (x + e0) ** -3, 2 * a1 * (x + e1) ** -3]
    g1 = lambda x: [2.0, -2.0, -6 * a0 * (x + e0) ** -4, -6 * a1 * (x + e1) ** -4]
    g2 = lambda x: [0.0, 0.0, 24 * a0 * (x + e0) ** -5, 24 * a1 * (x + e1) ** -5]
    S3 = np.linalg.solve([[1.0] * 4, g(1.0), g1(1.0), g2(1.0)], [1.0, 0, 0, 0])
    S4 = np.linalg.solve([[1.0] * 4, g(1.0), g1(1.0), g2(0.0)], [1.0, 0, 0, 0])
    return np.array([[0.5, 0.5, 0, 0], [0, 1.0, 0, 0], S3, S4])


#: hybrid4's curvature basis (numpy): S = BASIS @ (1 - mu^4, (1 - mu^2)^2, P_e0, P_e1)
BASIS = _basis()
_BASIS_T = BASIS.T
_LAW_CONST = {}


def _const(dt):
    """The tables as mx.arrays of dtype dt (made once per dtype)."""
    if dt not in _CONST:
        f = lambda a: mx.array(np.asarray(a, float), dtype=dt)
        _CONST[dt] = dict(X0=f(_X0), lo=f(_X.min(0)), Y=f(_Y), YN=f(_YN0), valid=mx.array(_VALID),
                          axes=[f(a) for a in _AXES], scale=f(SCALE), basis=f(_BASIS_T),
                          mu=f(_MU), eps=[float(e) for e in EPS],
                          **{k: f(v) for k, v in _LAW_CONST.items()})
    return _CONST[dt]


def _dtype(*args):
    """float32 if a float32 array is among args and no float64 one; else float64."""
    kinds = set()
    for a in args:
        if isinstance(a, mx.array):
            kinds.add("32" if a.dtype in (mx.float32, mx.float16, mx.bfloat16) else "64")
        elif isinstance(a, (np.ndarray, np.generic)):
            kinds.add("32" if a.dtype == np.float32 else "64")
    return mx.float32 if kinds == {"32"} else mx.float64


def _stream(dt):
    # MLX has no float64 on Metal: float64 work runs on the CPU stream
    return mx.stream(mx.cpu) if dt == mx.float64 else contextlib.nullcontext()


def _as(a, dt):
    if isinstance(a, mx.array):
        return a if a.dtype == dt else a.astype(dt)
    return mx.array(np.asarray(a, float), dtype=dt)


def _pole(mu, e):
    return ((mu * mu + e) ** -2 - (1 + e) ** -2) / (e ** -2 - (1 + e) ** -2)


def _shapes(mu, K):
    e0, e1 = K["eps"]
    T = mx.stack([1 - mu ** 4, (1 - mu ** 2) ** 2, _pole(mu, e0), _pole(mu, e1)], axis=-1)
    return T @ K["basis"]

def _intensity(c, mu, K):
    return 1.0 - c @ mx.transpose(_shapes(mu, K))


def _is_physical(c, K, dt):
    tol = 1e-10 if dt == mx.float64 else 1e-6           # float32 rounding of I near mu = 1
    I = _intensity(c, K["mu"], K)
    return (mx.all(mx.isfinite(I), axis=-1) & (I[..., 0] >= -tol)
            & mx.all(I[..., 1:] - I[..., :-1] >= -tol, axis=-1))


def _from_q(q, K):
    s, a, b = mx.power(q[..., 0], 0.25), mx.power(q[..., 1], 1 / 3), mx.sqrt(q[..., 2])
    return mx.stack([s * (1 - a), s * a * (1 - b), s * a * b * (1 - q[..., 3]), s * a * b * q[..., 3]], -1)


def _to_q(w, K):
    s = w.sum(-1)
    f = w / mx.where(s == 0, 1.0, s)[..., None]
    r1 = 1 - f[..., 0]
    r2 = mx.where(r1 == 0, 0.0, 1 - f[..., 1] / mx.where(r1 == 0, 1.0, r1))
    f34 = f[..., 2] + f[..., 3]
    q = mx.stack([mx.sign(s) * mx.abs(s) ** 4, mx.sign(r1) * mx.abs(r1) ** 3,   # keep the sign
                  mx.where(r2 >= 0, r2 * r2, r2),
                  mx.where(f34 == 0, 0.0, f[..., 3] / mx.where(f34 == 0, 1.0, f34))], -1)
    q = mx.where((s == 0)[..., None], 0.0, q)
    q = mx.where((q < 0) & (q > -1e-9), 0.0, q)           # rounding noise onto the bound
    return mx.where((q > 1) & (q < 1 + 1e-9), 1.0, q)


def _interpolate(x, extrapolate, K, dt):
    """Linear interpolation at scaled points x (n, 3): (n, NW + 2) values and
    the inside flag. The Kuhn tetrahedron of the grid box containing x is the
    one given by the order of x's fractional coordinates in the box."""
    tol = 1e-9 if dt == mx.float64 else 1e-5
    ii, ff = [], []
    for k, a in enumerate(K["axes"]):
        xk = x[:, k]
        i = mx.stop_gradient(mx.minimum((xk[:, None] >= a[None, 1:-1]).sum(-1),
                                        a.shape[0] - 2).astype(mx.int32))
        ii.append(i)
        ff.append((xk - a[i]) / (a[i + 1] - a[i]))
    i, f = mx.stack(ii, -1), mx.stack(ff, -1)
    inside = mx.all((f >= -tol) & (f <= 1 + tol), axis=-1)
    order = mx.stop_gradient(mx.argsort(-f, axis=-1))       # indices: no gradient
    fs = mx.take_along_axis(f, order, axis=-1)
    lam = mx.stack([1 - fs[:, 0], fs[:, 0] - fs[:, 1], fs[:, 1] - fs[:, 2], fs[:, 2]], -1)
    E = mx.eye(3, dtype=mx.int32)
    v = [i]
    for j in range(3):
        v.append(v[-1] + E[order[:, j]])
    v = mx.stack(v, 1)                                      # (n, 4, 3) grid indices
    node = mx.stop_gradient((v[..., 0] * _SHAPE[1] + v[..., 1]) * _SHAPE[2] + v[..., 2])
    inside = inside & ~mx.any((lam > tol) & ~K["valid"][node], axis=-1)
    y = (lam[..., None] * K["YN"][node]).sum(1)
    if extrapolate:
        x0, X0 = x - K["lo"], K["X0"]
        d2 = (x0 * x0).sum(-1, keepdims=True) - 2.0 * (x0 @ mx.transpose(X0)) + (X0 * X0).sum(-1)
        y = mx.where(inside[:, None], y, K["Y"][mx.stop_gradient(mx.argmin(d2, axis=-1))])
    else:
        y = mx.where(inside[:, None], y, mx.nan)
    return y, inside


def coefficients(teff, logg, mh, extrapolate=False, correction=None):
    """Interpolated hybrid4 coefficients at (Teff [K], log g [cgs], [M/H]):
    numbers, numpy or mx arrays, broadcast against each other. Returns
    dict(coeffs, w, q, physical, mu_cri, lc_ppm, inside, correction) of mx.arrays,
    coeffs, w, q with a trailing axis of 4. Outside the grid the outputs are
    NaN (inside False) unless extrapolate=True, which uses the nearest model."""
    if correction is not None:
        if correction not in _CORR:
            raise ValueError(f"correction must be one of {tuple(_CORR)}")
        if not isinstance(teff, mx.array) and np.any((np.asarray(teff) < _CORR_TEFF[0])
                                                       | (np.asarray(teff) > _CORR_TEFF[-1])):
            warnings.warn("Teff outside the MURaM range: correction clamped", stacklevel=2)
    dt = _dtype(teff, logg, mh)
    with _stream(dt):
        K = _const(dt)
        t, g, m = mx.broadcast_arrays(_as(teff, dt), _as(logg, dt), _as(mh, dt))
        shape = t.shape
        x = mx.stack([t.reshape(-1), g.reshape(-1), m.reshape(-1)], axis=-1) / K["scale"]
        y, inside = _interpolate(x, extrapolate, K, dt)
        c = y[:, :NW]
        if correction is not None:
            c = c + _delta_w(t.reshape(-1), correction, dt)
        cs = c.reshape(shape + (NW,))
        return dict(coeffs=cs, w=cs, q=_to_q(c, K).reshape(shape + (NW,)),
                    physical=_is_physical(c, K, dt).reshape(shape), mu_cri=y[:, NW].reshape(shape),
                    lc_ppm=y[:, NW + 1].reshape(shape), inside=inside.reshape(shape), correction=correction)


def shapes(mu):
    """The law's shapes at mu (m,): shape (m, NW)."""
    dt = _dtype(mu)
    with _stream(dt):
        return _shapes(_as(mu, dt), _const(dt))


def intensity(w, mu):
    """I(mu)/I(1) for hybrid4 coefficients w (..., 4) at mu (m,): shape (..., m)."""
    dt = _dtype(w, mu)
    with _stream(dt):
        return _intensity(_as(w, dt), _as(mu, dt), _const(dt))


def is_physical(w):
    """Positive and non-increasing towards the limb on 2001 points in mu: shape (...)."""
    dt = _dtype(w)
    with _stream(dt):
        return _is_physical(_as(w, dt), _const(dt), dt)


def from_q(q):
    """Coefficients (..., NW) from sampling coordinates q in [0, 1]^NW (no clamp:
    the gradient is infinite where a q_j is 0; Elómë's from_q clamps it)."""
    dt = _dtype(q)
    with _stream(dt):
        return _from_q(_as(q, dt), _const(dt))


def to_q(c):
    """Sampling coordinates (..., NW) of coefficients c (outside [0, 1] if outside the region)."""
    dt = _dtype(c)
    with _stream(dt):
        return _to_q(_as(c, dt), _const(dt))


if __name__ == "__main__":
    import sys
    t, g, m = (float(v) for v in sys.argv[1:4]) if len(sys.argv) >= 4 else (5600.0, 4.4, 0.0)
    r = coefficients(t, g, m, extrapolate=True)
    print(f"hybrid4 {GRID} {BAND} Teff={t:g} logg={g:g} [M/H]={m:+g}:",
          " ".join(f"{k}={v:.6f}" for k, v in zip(NAMES, r["coeffs"].tolist())),
          "q =", " ".join(f"{v:.6f}" for v in r["q"].tolist()),
          "physical" if r["physical"].item() else "UNPHYSICAL",
          "" if r["inside"].item() else "(nearest model; outside grid)")
